        mem, ts = stack.pop()
        terminal = True
        for i in range(n):
            pc, buf, obs = ts[i]
            if pc < len(progs[i]):
                terminal = False
                ins = progs[i][pc]
                op = ins[0]
                if op == 'store':
                    nts = list(ts)
                    nts[i] = (pc + 1, buf + ((ins[1], ins[2], ins[3]),), obs)
                    s = (mem, tuple(nts))
                    if s not in visited:
                        visited.add(s); stack.append(s)
