                            sa, sw, sv = buf[k]
                            if sa <= b < sa + sw:
                                val = (sv >> (8 * (b - sa))) & 0xFF
                                break
                        if val is None:
                            val = mem[b]
                        v |= val << (8 * j)
                    nts = list(ts)
                    nts[i] = (pc + 1, buf, obs + (v,))
                    s = (mem, tuple(nts))
                    if s not in visited:
                        visited.add(s); stack.append(s)
                elif op == 'fence':
                    if not buf:
                        nts = list(ts)
                        nts[i] = (pc + 1, buf, obs)
                        s = (mem, tuple(nts))
                        if s not in visited:
                            visited.add(s); stack.append(s)
                else:  # xchg
                    if not buf:
                        addr, width, val = ins[1], ins[2], ins[3]
                        old = 0
                        m = list(mem)
                        for j in range(width):
                            old |= mem[addr + j] << (8 * j)
                            m[addr + j] = (val >> (8 * j)) & 0xFF
                        nts = list(ts)
                        nts[i] = (pc + 1, buf, obs + (old,))
                        s = (tuple(m), tuple(nts))
                        if s not in visited:
                            visited.add(s); stack.append(s)
        for i in range(n):
            pc, buf, obs = ts[i]
            if buf:
                terminal = False
                sa, sw, sv = buf[0]
                m = list(mem)
                for j in range(sw):
                    m[sa + j] = (sv >> (8 * j)) & 0xFF
