                s = (tuple(m), tuple(nts))
                if s not in visited:
                    visited.add(s); stack.append(s)
        if terminal:
            outcomes.add((tuple(t[2] for t in ts), mem))
    return {'outcomes': [{'reads': [list(o) for o in obs], 'memory': list(mem)}
