import json, sys, itertools, random
sys.setrecursionlimit(100000)

def brute(request):
    mem0 = tuple(request['memory'])
    progs = request['threads']
    n = len(progs)
    outcomes = set()
    def rec(mem, ts):
        enabled = []
        for i in range(n):
            pc, buf, obs = ts[i]
            if pc < len(progs[i]):
                ins = progs[i][pc]; op = ins[0]
                if op in ('fence','xchg') and buf:
                    continue
                enabled.append(('exec', i))
        for i in range(n):
            if ts[i][1]:
                enabled.append(('drain', i))
        if not enabled:
            outcomes.add((tuple(t[2] for t in ts), mem))
            return
        for kind, i in enabled:
            pc, buf, obs = ts[i]
            if kind == 'drain':
                sa, sw, sv = buf[0]
                m = list(mem)
                for j in range(sw): m[sa+j] = (sv >> (8*j)) & 0xFF
                nts = list(ts); nts[i] = (pc, buf[1:], obs)
                rec(tuple(m), tuple(nts))
            else:
                ins = progs[i][pc]; op = ins[0]
                if op == 'store':
                    nts = list(ts); nts[i] = (pc+1, buf+((ins[1],ins[2],ins[3]),), obs)
                    rec(mem, tuple(nts))
                elif op == 'load':
                    addr, width = ins[1], ins[2]; v = 0
                    for j in range(width):
                        b = addr+j; val = None
                        for k in range(len(buf)-1, -1, -1):
                            sa, sw, sv = buf[k]
                            if sa <= b < sa+sw:
                                val = (sv >> (8*(b-sa))) & 0xFF; break
                        if val is None: val = mem[b]
                        v |= val << (8*j)
                    nts = list(ts); nts[i] = (pc+1, buf, obs+(v,))
                    rec(mem, tuple(nts))
                elif op == 'fence':
                    nts = list(ts); nts[i] = (pc+1, buf, obs)
                    rec(mem, tuple(nts))
                else:
                    addr, width, val = ins[1], ins[2], ins[3]
                    old = 0; m = list(mem)
                    for j in range(width):
                        old |= mem[addr+j] << (8*j)
                        m[addr+j] = (val >> (8*j)) & 0xFF
                    nts = list(ts); nts[i] = (pc+1, buf, obs+(old,))
                    rec(tuple(m), tuple(nts))
    rec(mem0, tuple((0, (), ()) for _ in range(n)))
    return outcomes

import main
random.seed(42)
for trial in range(400):
    nmem = random.randint(1, 6)
    mem = [random.randint(0, 3) for _ in range(nmem)]
    nt = random.randint(1, 3)
    total = 0; threads = []
    for t in range(nt):
        k = random.randint(0, 3)
        total += k
        if total > 6: k -= total - 6; total = 6
        prog = []
        for _ in range(k):
            w = random.choice([1, 2, 4])
            if w > nmem: w = 1
            a = random.randint(0, nmem - w)
            op = random.choice(['store','load','fence','xchg'])
            if op == 'store': prog.append(['store', a, w, random.randint(0, (1<<(8*w))-1) % 5])
            elif op == 'load': prog.append(['load', a, w])
            elif op == 'fence': prog.append(['fence'])
            else: prog.append(['xchg', a, w, random.randint(0, 4)])
        threads.append(prog)
    req = {'memory': mem, 'threads': threads}
    got = main.solve(req)
